-- Create function to get user emails safely (admin only)
CREATE OR REPLACE FUNCTION public.get_user_emails_for_admin()
RETURNS TABLE (
  user_id UUID,
  email TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Only allow admins to call this function
  IF NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Access denied: Admin role required';
  END IF;
  
  RETURN QUERY
  SELECT au.id as user_id, au.email::text
  FROM auth.users au;
END;
$$;
$ether_m35s4$;
  EXECUTE $ether_m35s5$
-- Create function to get all user data for admin dashboard
CREATE OR REPLACE FUNCTION public.get_admin_user_data()
RETURNS TABLE (
  user_id UUID,
  email TEXT,
  display_name TEXT,
  phone TEXT,
  city TEXT,
  mindset_level INTEGER,
  access_status TEXT,
  created_at TIMESTAMP WITH TIME ZONE
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Only allow admins to call this function
  IF NOT has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Access denied: Admin role required';
  END IF;
  
  RETURN QUERY
  SELECT 
    p.user_id,
    au.email::text,
    p.display_name,
    p.phone,
    p.city,
    p.mindset_level,
    p.access_status,
    p.created_at
  FROM public.profiles p
  LEFT JOIN auth.users au ON au.id = p.user_id;
END;
$$;
