CREATE POLICY "Project creators can view project conversations"
ON public.conversations
FOR SELECT
USING (
  project_id IS NOT NULL 
  AND EXISTS (
    SELECT 1 FROM projects p
    WHERE p.id = conversations.project_id
    AND p.creator_id = auth.uid()
  )
);
