-- Backfill event_type from legacy ticket_type
UPDATE public.events
SET event_type = CASE
  WHEN ticket_type = 'paid' OR (ticket_price IS NOT NULL AND ticket_price > 0) THEN 'paid_ticket'
  WHEN ticket_type = 'credits' THEN 'paid_ticket'
  ELSE 'free_rsvp'
