CREATE OR REPLACE FUNCTION public.city_to_state(input text)
RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path = public AS $$
DECLARE c text;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  c := lower(trim(input));
  c := regexp_replace(c, ',.*$', '');
