  TO authenticated
  USING (auth.uid() = user_id);
$ether_m133s12$;
  EXECUTE $ether_m133s13$
-- profiles_public is the only way to read someone else.
-- security_invoker is off so own-row RLS does not hide every other row.
-- The WHERE clause is the visibility rule. Phone and onboarding_score
-- are not selected.
DROP VIEW IF EXISTS public.profiles_public;
$ether_m133s13$;
  EXECUTE $ether_m133s14$
CREATE VIEW public.profiles_public
WITH (security_barrier = true, security_invoker = false) AS
SELECT
  p.id,
  p.user_id,
  p.display_name,
  p.city,
  p.city_display,
  p.city_key,
  p.bio,
  p.avatar_url,
  p.passion_seriousness,
  p.access_level,
  p.onboarding_completed,
  p.created_at,
  p.updated_at,
  p.mindset_level,
  p.access_status,
  p.social_links,
  p.is_suspended,
  p.suspended_at,
  p.suspension_reason,
  p.onboarding_level
FROM public.profiles p
WHERE
  p.user_id = auth.uid()
  OR COALESCE(p.show_only_to_passed_exam, false) = false
  OR public.has_role(auth.uid(), 'admin')
  OR EXISTS (
    SELECT 1
    FROM public.profiles viewer
    WHERE viewer.user_id = auth.uid()
      AND viewer.passed_exam = true
  );
$ether_m133s14$;
  EXECUTE $ether_m133s15$
GRANT SELECT ON public.profiles_public TO anon, authenticated;
