CREATE OR REPLACE FUNCTION public.enforce_report_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to report'
      USING ERRCODE = '42501';
  END IF;

  NEW.reporter_id := auth.uid();
  NEW.status := 'open';
  NEW.reviewed_by := NULL;
  NEW.reviewed_at := NULL;
  NEW.created_at := now();
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;
