-- 20261018204000_reconcile_credit_balances.sql
DO $ether_m140$
BEGIN
  IF EXISTS (SELECT 1 FROM public.ether_schema_migrations WHERE version = '20261018204000_reconcile_credit_balances.sql') THEN
    RAISE NOTICE 'skip 20261018204000_reconcile_credit_balances.sql';
    RETURN;
  END IF;
  EXECUTE $ether_m140s0$
-- =============================================================================
-- Cadre approved this rewrite. It has not been applied to any live database.
-- Run it on staging first. Re-running it is safe: the UPDATE only rewrites
-- stored pools from the ledger, and the check is dropped before it is added.
-- =============================================================================
-- One-time reconciliation. This file rewrites public.user_credits from
-- public.credit_ledger. It does not insert or delete ledger rows.
--
-- Why: grant_genesis_credits used to write a 100 balance and also insert a
-- ledger row. The ledger trigger added 100 again, so new users showed
-- balance 200 while the ledger said 100. Other rows with earned_amount 0
-- added amount to balance and 0 to the earned pool.
--
-- What it does:
--   1. Recomputes genesis_balance and earned_balance with ledger_entry_deltas
--      (the same rule as update_user_credits_dual).
--   2. Sets balance = genesis_balance + earned_balance.
--   3. For users who have no ledger rows, only repairs a broken sum.
--   4. Adds CHECK (balance = genesis_balance + earned_balance).
--
-- Scratch tests apply it to an empty database, then insert users and check
-- that a new signup is 100, not 200. Do not apply it to production until
-- staging has been checked.
-- =============================================================================

UPDATE public.user_credits uc
SET
  genesis_balance = d.genesis_balance,
  earned_balance = d.earned_balance,
  balance = d.genesis_balance + d.earned_balance,
  genesis_lifetime_minted = GREATEST(uc.genesis_lifetime_minted, d.genesis_minted),
  genesis_burned = d.genesis_burned,
  lifetime_earned = d.lifetime_earned,
  lifetime_spent = d.lifetime_spent,
  updated_at = now()
FROM (
  SELECT
    l.user_id,
    COALESCE(SUM(x.genesis_delta), 0) AS genesis_balance,
    COALESCE(SUM(x.earned_delta), 0) AS earned_balance,
    COALESCE(SUM(CASE WHEN x.genesis_delta > 0 THEN x.genesis_delta ELSE 0 END), 0) AS genesis_minted,
    COALESCE(SUM(
      CASE
        WHEN l.credit_type = 'genesis' AND l.type IN ('spend', 'transfer_out') THEN ABS(x.genesis_delta)
        ELSE 0
      END
    ), 0) AS genesis_burned,
    COALESCE(SUM(CASE WHEN x.earned_delta > 0 THEN x.earned_delta ELSE 0 END), 0) AS lifetime_earned,
    COALESCE(SUM(CASE WHEN l.amount < 0 THEN ABS(l.amount) ELSE 0 END), 0) AS lifetime_spent
  FROM public.credit_ledger l
  CROSS JOIN LATERAL public.ledger_entry_deltas(
    l.credit_type, l.amount, l.genesis_amount, l.earned_amount
  ) x
  GROUP BY l.user_id
) d
WHERE uc.user_id = d.user_id;
$ether_m140s0$;
  EXECUTE $ether_m140s1$
-- Users with no ledger row keep their pools. Only the sum is repaired so the
-- check below can be added. This does not mint or burn credits.
UPDATE public.user_credits uc
SET
  balance = genesis_balance + earned_balance,
  updated_at = now()
WHERE balance IS DISTINCT FROM (genesis_balance + earned_balance)
  AND NOT EXISTS (
    SELECT 1 FROM public.credit_ledger l WHERE l.user_id = uc.user_id
  );
$ether_m140s1$;
  EXECUTE $ether_m140s2$
ALTER TABLE public.user_credits
  DROP CONSTRAINT IF EXISTS user_credits_balance_matches_pools;
$ether_m140s2$;
  EXECUTE $ether_m140s3$
ALTER TABLE public.user_credits
  ADD CONSTRAINT user_credits_balance_matches_pools
  CHECK (balance = genesis_balance + earned_balance);
$ether_m140s3$;
  EXECUTE $ether_m140s4$
-- Read-only check Cadre can run after the rewrite:
--   SELECT * FROM public.user_credits_pool_check WHERE NOT pools_match;
CREATE OR REPLACE VIEW public.user_credits_pool_check
WITH (security_invoker = true) AS
SELECT
  user_id,
  balance,
  genesis_balance,
  earned_balance,
  (balance = genesis_balance + earned_balance) AS pools_match
FROM public.user_credits;
$ether_m140s4$;
  EXECUTE $ether_m140s5$
GRANT SELECT ON public.user_credits_pool_check TO authenticated, service_role;
$ether_m140s5$;
  INSERT INTO public.ether_schema_migrations (version) VALUES ('20261018204000_reconcile_credit_balances.sql');
END
$ether_m140$;

-- 20261018205000_ledger_spend_and_private_xp.sql
DO $ether_m141$
BEGIN
  IF EXISTS (SELECT 1 FROM public.ether_schema_migrations WHERE version = '20261018205000_ledger_spend_and_private_xp.sql') THEN
    RAISE NOTICE 'skip 20261018205000_ledger_spend_and_private_xp.sql';
    RETURN;
  END IF;
  EXECUTE $ether_m141s0$
-- Spend checks read credit_ledger_balances, the same sums the wallet shows.
-- user_credits stays a cache the ledger trigger maintains.
--
-- XP is a separate private ledger. Triggers award it. Clients cannot insert
-- rows or call award_xp. Level is derived from the sum and is only returned
-- for auth.uid(). This file has not been applied to any live database.

-- ---------------------------------------------------------------------------
-- Tips lock the cache row, then spend the ledger totals.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.apply_stream_tip(
  p_tipper uuid,
  p_stream_id uuid,
  p_amount integer,
  p_message text,
  p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_host uuid;
  v_title text;
  v_genesis numeric;
  v_earned numeric;
  v_genesis_spend integer;
  v_earned_spend integer;
  v_total numeric;
  v_host_balance numeric;
BEGIN
  IF p_tipper IS NULL OR p_amount IS NULL OR p_amount < 1 THEN
    RAISE EXCEPTION 'Invalid tip';
  END IF;
  IF auth.uid() IS DISTINCT FROM p_tipper
     AND current_user NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'idempotency key required';
  END IF;

  SELECT host_id, title INTO v_host, v_title
  FROM public.live_streams
  WHERE id = p_stream_id;
  IF v_host IS NULL THEN
    RAISE EXCEPTION 'Stream not found';
  END IF;
  IF v_host = p_tipper THEN
    RAISE EXCEPTION 'Cannot tip your own stream';
  END IF;

  BEGIN
    INSERT INTO public.stream_tips (stream_id, tipper_id, host_id, amount, message, idempotency_key)
    VALUES (p_stream_id, p_tipper, v_host, p_amount, NULLIF(btrim(COALESCE(p_message, '')), ''), p_idempotency_key);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true);
  END;

  INSERT INTO public.user_credits (user_id, balance, genesis_balance, earned_balance, lifetime_earned, lifetime_spent)
  VALUES (p_tipper, 0, 0, 0, 0, 0)
  ON CONFLICT (user_id) DO NOTHING;

  PERFORM 1
  FROM public.user_credits
  WHERE user_id = p_tipper
  FOR UPDATE;

  v_genesis := (public.credit_ledger_balances(p_tipper)->>'genesis_balance')::numeric;
  v_earned := (public.credit_ledger_balances(p_tipper)->>'earned_balance')::numeric;
  v_total := COALESCE(v_genesis, 0) + COALESCE(v_earned, 0);
  IF v_total < p_amount THEN
    RAISE EXCEPTION 'Insufficient credits';
  END IF;

  IF COALESCE(v_genesis, 0) >= p_amount THEN
    v_genesis_spend := p_amount;
    v_earned_spend := 0;
  ELSE
    v_genesis_spend := COALESCE(v_genesis, 0)::integer;
    v_earned_spend := p_amount - v_genesis_spend;
  END IF;

  IF v_genesis_spend > 0 THEN
    INSERT INTO public.credit_ledger (
      user_id, amount, balance_after, type, description,
      credit_type, genesis_amount, earned_amount, reference_type, reference_id
    ) VALUES (
      p_tipper, -v_genesis_spend, v_total - v_genesis_spend, 'spend',
      'Tip to stream: ' || COALESCE(v_title, 'live'),
      'genesis', -v_genesis_spend, 0, 'stream_tip', p_stream_id
    );
  END IF;

  IF v_earned_spend > 0 THEN
    INSERT INTO public.credit_ledger (
      user_id, amount, balance_after, type, description,
      credit_type, genesis_amount, earned_amount, reference_type, reference_id
    ) VALUES (
      p_tipper, -v_earned_spend, v_total - p_amount, 'spend',
      'Tip to stream: ' || COALESCE(v_title, 'live'),
      'earned', 0, -v_earned_spend, 'stream_tip', p_stream_id
    );
  END IF;

  v_host_balance := COALESCE((public.credit_ledger_balances(v_host)->>'balance')::numeric, 0);

  INSERT INTO public.credit_ledger (
    user_id, amount, balance_after, type, description,
    credit_type, genesis_amount, earned_amount, reference_type, reference_id
  ) VALUES (
    v_host, p_amount, v_host_balance + p_amount, 'earn',
    'Tip received on stream',
    'earned', 0, p_amount, 'stream_tip', p_stream_id
  );

  PERFORM public.increment_stream_tips(p_stream_id, p_amount);

  INSERT INTO public.notifications (user_id, type, title, body, data)
  VALUES (
    v_host, 'stream_tip', 'You received a tip!',
    'Someone tipped you ' || p_amount || ' LC on your stream',
    jsonb_build_object('stream_id', p_stream_id, 'amount', p_amount)
  );

  RETURN jsonb_build_object(
    'success', true,
    'idempotent', false,
    'genesis_spent', v_genesis_spend,
    'earned_spent', v_earned_spend
  );
END;
$$;
$ether_m141s0$;
  EXECUTE $ether_m141s1$
-- Admin list uses the same ledger sums. Non-admins cannot call it.
CREATE OR REPLACE FUNCTION public.credit_balance_rows()
RETURNS TABLE (user_id uuid, balance numeric, genesis_balance numeric, earned_balance numeric)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- current_user is the owner inside this definer function, so the admin
  -- check has to use the caller's auth.uid().
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  RETURN QUERY
  SELECT
    l.user_id,
    COALESCE(SUM(d.genesis_delta + d.earned_delta), 0),
    COALESCE(SUM(d.genesis_delta), 0),
    COALESCE(SUM(d.earned_delta), 0)
  FROM public.credit_ledger l
  CROSS JOIN LATERAL public.ledger_entry_deltas(
    l.credit_type, l.amount, l.genesis_amount, l.earned_amount
  ) d
  GROUP BY l.user_id;
END;
$$;
$ether_m141s1$;
  EXECUTE $ether_m141s2$
REVOKE ALL ON FUNCTION public.credit_balance_rows() FROM PUBLIC;
$ether_m141s2$;
  EXECUTE $ether_m141s3$
GRANT EXECUTE ON FUNCTION public.credit_balance_rows() TO authenticated, service_role;
