RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
  SELECT jsonb_build_object(
    'total', COALESCE(SUM(amount), 0),
    'level', public.xp_level(COALESCE(SUM(amount), 0)::integer)
  )
  FROM public.xp_events
  WHERE user_id = auth.uid();
$$;
