RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF COALESCE(btrim(NEW.content), '') <> '' OR COALESCE(btrim(NEW.media_url), '') <> '' THEN
    PERFORM public.award_xp(NEW.user_id, 'post_work', NEW.id, 10);
