CREATE OR REPLACE FUNCTION public.invite_waitlist(p_ids uuid[])
RETURNS TABLE (
  id uuid,
  email text,
  invite_token text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_id uuid;
  v_token text;
  alphabet text := 'abcdefghjkmnpqrstuvwxyz23456789';
  i integer;
  n integer;
  attempt integer;
BEGIN
  IF NOT public.waitlist_admin_allowed() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN
    RAISE EXCEPTION 'select someone';
  END IF;

  FOREACH v_id IN ARRAY p_ids LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.waitlist w WHERE w.id = v_id AND w.converted_at IS NULL
    ) THEN
      CONTINUE;
    END IF;
    v_token := NULL;
    FOR attempt IN 1..8 LOOP
      v_token := '';
      FOR i IN 1..24 LOOP
        n := 1 + floor(random() * length(alphabet))::integer;
        v_token := v_token || substr(alphabet, n, 1);
      END LOOP;
      BEGIN
        UPDATE public.waitlist w
        SET invited_at = now(),
            invite_token = v_token
        WHERE w.id = v_id
          AND w.converted_at IS NULL;
        EXIT;
      EXCEPTION
        WHEN unique_violation THEN
          v_token := NULL;
      END;
    END LOOP;
    IF v_token IS NOT NULL THEN
      id := v_id;
      email := (SELECT w.email FROM public.waitlist w WHERE w.id = v_id);
      invite_token := v_token;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$fn$;
$ether_m160s17$;
  EXECUTE $ether_m160s18$
