-- 20261020165000_claim_waitlist_on_signup.sql
DO $ether_m162$
BEGIN
  IF EXISTS (SELECT 1 FROM public.ether_schema_migrations WHERE version = '20261020165000_claim_waitlist_on_signup.sql') THEN
    RAISE NOTICE 'skip 20261020165000_claim_waitlist_on_signup.sql';
