-- 20261020172000_collab_invites.sql
DO $ether_m165$
BEGIN
  IF EXISTS (SELECT 1 FROM public.ether_schema_migrations WHERE version = '20261020172000_collab_invites.sql') THEN
    RAISE NOTICE 'skip 20261020172000_collab_invites.sql';
    RETURN;
