CREATE OR REPLACE FUNCTION public.either_blocked(a uuid, b uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT a IS NOT NULL
    AND b IS NOT NULL
    AND a <> b
    AND (
      public.has_blocked(a, b)
      OR public.has_blocked(b, a)
    );
$$;
