-- 20261023150000_event_guest_list.sql
DO $ether_m175$
BEGIN
  IF EXISTS (SELECT 1 FROM public.ether_schema_migrations WHERE version = '20261023150000_event_guest_list.sql') THEN
    RAISE NOTICE 'skip 20261023150000_event_guest_list.sql';
