CREATE POLICY "Anyone can view public events"
  ON public.events
  FOR SELECT
  USING (
    public.has_role(auth.uid(), 'admin')
    OR (
      removed_at IS NULL
      AND (
        (hidden_at IS NULL AND is_public = true)
        OR (auth.uid() IS NOT NULL AND creator_id = auth.uid())
      )
    )
  );
