-- Hosts can refill the address field. Guests still go through public_event_location.
CREATE OR REPLACE FUNCTION public.host_event_address(p_event_id uuid)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_address text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.events e
    WHERE e.id = p_event_id
      AND (e.creator_id = auth.uid() OR public.can_manage_event(p_event_id, auth.uid()))
  ) THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(s.private_address, e.address)
    INTO v_address
  FROM public.events e
  LEFT JOIN public.event_secrets s ON s.event_id = e.id
  WHERE e.id = p_event_id;
  RETURN v_address;
END;
$$;
$ether_m182s27$;
  EXECUTE $ether_m182s28$
REVOKE ALL ON FUNCTION public.host_event_address(uuid) FROM PUBLIC;
$ether_m182s28$;
  EXECUTE $ether_m182s29$
GRANT EXECUTE ON FUNCTION public.host_event_address(uuid) TO authenticated;
$ether_m182s29$;
  EXECUTE $ether_m182s30$
-- Guest pages read these columns. The anon grant on events is column-level.
GRANT SELECT (
  video_url,
  flyer_font,
  page_theme,
  hide_address,
  absorb_fees,
  password_protected
) ON public.events TO anon;
$ether_m182s30$;
  EXECUTE $ether_m182s31$
-- Signed-out guests cannot read event_rsvps, and they cannot execute
-- can_manage_event. The older moodboard SELECT policies use both, so an
-- anon read fails before a public event can be shown. Those policies stay
-- for signed-in members. Anon only checks events.id and events.is_public.
ALTER POLICY "Moodboard viewable for public events or attendees"
  ON public.event_moodboard_items
  TO authenticated;
$ether_m182s31$;
  EXECUTE $ether_m182s32$
ALTER POLICY "Public can view moodboard for public events"
  ON public.event_moodboard_items
  TO authenticated;
$ether_m182s32$;
  EXECUTE $ether_m182s33$
DROP POLICY IF EXISTS "Anon can view moodboard for public events" ON public.event_moodboard_items;
$ether_m182s33$;
  EXECUTE $ether_m182s34$
CREATE POLICY "Anon can view moodboard for public events"
ON public.event_moodboard_items
FOR SELECT
TO anon
USING (
  EXISTS (
    SELECT 1 FROM public.events e
    WHERE e.id = event_id
      AND e.is_public
  )
);
$ether_m182s34$;
  INSERT INTO public.ether_schema_migrations (version) VALUES ('20261024140000_event_hosting.sql');
END
